#!/usr/bin/env python3
"""Integrate a draft with complete failed-native observations and strict child checks."""
import base64,hashlib,io,json,os,pathlib,subprocess,tarfile,time
ROOT=pathlib.Path('/home/qian-qi/chain-pon-followthrough-20261110-685a')
INPUTS=pathlib.Path(str(ROOT)+'-inputs')
BUNDLE=INPUTS/'integration-bundle-02'
OUT=INPUTS/'integration-driver-02'
INTEGRATED=INPUTS/'integration-02'
NATIVE=INPUTS/'binding-native-02'
TARGET=pathlib.Path(str(ROOT)+'-target')
VALIDATION=INPUTS/'validation'
FOLLOWUP=INPUTS/'native-followup-04'
C2='8d8c0e64e7a301fc111a6720721a14816639e5aa'
ARCHIVE=base64.b64decode('')
NATIVE_SCRIPT=base64.b64decode('')
ENV=dict(os.environ,PATH='/home/qian-qi/.cargo/bin:'+os.environ.get('PATH',''),PYTHONDONTWRITEBYTECODE='1',CARGO_BUILD_JOBS='2',CARGO_TARGET_DIR=str(TARGET),CARGO_TERM_COLOR='never')
def sha(data): return hashlib.sha256(data).hexdigest()
def emit(path,value):
    raw=(json.dumps(value,indent=2,sort_keys=True)+'\n').encode()
    temporary=path.with_suffix(path.suffix+'.tmp')
    with temporary.open('xb') as stream: stream.write(raw);stream.flush();os.fsync(stream.fileno())
    temporary.replace(path)
def status(stage,phase,code=None,details=None):
    emit(OUT/'status.json',dict(stage=stage,phase=phase,exit_code=code,details=details,recorded_unix_ns=time.time_ns(),security_status='HOLD'))
def run(label,argv):
    status(label,'running'); start=time.time_ns()
    stdout,stderr=OUT/(label+'.stdout.log'),OUT/(label+'.stderr.log')
    with stdout.open('xb') as output,stderr.open('xb') as error:
        result=subprocess.run(argv,cwd=ROOT,env=ENV,stdout=output,stderr=error)
    record=dict(label=label,argv=argv,cwd=str(ROOT),exit_code=result.returncode,start_unix_ns=start,end_unix_ns=time.time_ns())
    for name,path in [('stdout',stdout),('stderr',stderr)]:
        raw=path.read_bytes();record[name]=dict(file=path.name,bytes=len(raw),sha256=sha(raw))
    emit(OUT/(label+'.command.json'),record)
    status(label,'finished' if result.returncode==0 else 'failed',result.returncode)
    if result.returncode: raise RuntimeError(label+' actual exit '+str(result.returncode))
    return record
assert sha(ARCHIVE)=='4d982f68de64051aba1345716ca926918bf5f92bdfb48cf3c69cc493b4c72cd6'
assert sha(NATIVE_SCRIPT)=='2613c863a3ff1c554196ff04d946738c55e763b1858ec627f4a0f9c35589891e'
assert INPUTS.is_dir() and INPUTS==INPUTS.resolve()
assert not OUT.exists() and not BUNDLE.exists() and not INTEGRATED.exists() and not NATIVE.exists()
OUT.mkdir(); status('bundle','running')
try:
    with tarfile.open(fileobj=io.BytesIO(ARCHIVE),mode='r:gz') as tar:
        members=tar.getmembers()
        assert len(members)==14 and len({x.name for x in members})==14
        assert all(x.isfile() and not x.name.startswith('/') and all(p not in ('','.','..') for p in x.name.split('/')) for x in members)
        assert sum(x.size for x in members)<512*1024
        payload={x.name:tar.extractfile(x).read() for x in members}
    manifest=json.loads(payload['integration/controller-input-manifest-v2.json'])
    assert set(payload)=={x['path'] for x in manifest['files']}|{'integration/controller-input-manifest-v2.json'}
    assert manifest['frozen'] is True and manifest['controller_sha256']=='725a000ab299079e96192c6e81b3c2d809203d3052947a947f104d3d4d0f70b5'
    for entry in manifest['files']:
        raw=payload[entry['path']]; assert len(raw)==entry['bytes'] and sha(raw)==entry['sha256']
    BUNDLE.mkdir()
    for name,raw in payload.items():
        path=BUNDLE/name;path.parent.mkdir(parents=True,exist_ok=True)
        with path.open('xb') as stream:stream.write(raw)
    native_path=OUT/'validate_binding_native.py'
    with native_path.open('xb') as stream:stream.write(NATIVE_SCRIPT)
    emit(OUT/'bundle.json',dict(archive_sha256=sha(ARCHIVE),member_count=len(payload),controller_sha256=manifest['controller_sha256'],native_runner_sha256=sha(NATIVE_SCRIPT)))
    original=json.loads((VALIDATION/'source-v3.json').read_bytes())
    assert original['commit']==C2 and original['clean'] is True
    followup_raw=(FOLLOWUP/'summary.json').read_bytes()
    assert sha(followup_raw)=='f6693ac2f41c9906f0a01a013e89a00200b844c4a9a78f24decdcb3fc93b0271'
    summary=json.loads(followup_raw)
    assert summary['observation_complete'] is True and summary['source']==C2
    assert summary['original_full_node_suite_passed'] is False and summary['all_followup_checks_passed'] is False
    assert summary['open_consensus_qualified'] is False and summary['production_activation'] is False
    with (OUT/'observed-native-followup-summary.json').open('xb') as stream:stream.write(followup_raw)
    run('integrate', ['python3','-B',str(BUNDLE/'integration/integrate_candidate_v2.py'),'--phase','all','--root',str(ROOT),'--inputs',str(BUNDLE),'--native-validation',str(VALIDATION),'--native-followup',str(FOLLOWUP),'--output',str(INTEGRATED)])
    integrated=json.loads((INTEGRATED/'summary.json').read_bytes())
    assert integrated['requested_phase_complete'] is True and integrated['integration_complete'] is True and integrated['state']=='validated'
    assert integrated['native_observation_complete'] is True and integrated['native_full_suite_passed'] is False and integrated['draft_only'] is True
    assert integrated['open_consensus_qualified'] is False and integrated['production_activation'] is False
    run('binding-native', ['python3','-B',str(native_path),'--root',str(ROOT),'--integration-output',str(INTEGRATED),'--output',str(NATIVE),'--target',str(TARGET)])
    checked=json.loads((NATIVE/'summary.json').read_bytes())
    assert checked['complete'] is True and checked['strict_clippy_passed'] is True
    result=dict(schema='pon-followthrough-gated-driver-v2',complete=True,native_observation_complete=True,native_full_suite_passed=False,draft_only=True,open_consensus_qualified=False,code_checkpoint_c2=C2,binding_child_c3=integrated['binding_child_c3'],binding_child_tree=integrated['binding_child_tree'],integration_complete=True,binding_native_complete=True,published=False,production_activation=False,security_status='HOLD')
    emit(OUT/'summary.json',result);status('complete','finished',0);print(json.dumps(result),flush=True)
except BaseException as error:
    emit(OUT/'failure.json',dict(complete=False,reason=repr(error),recorded_unix_ns=time.time_ns(),no_automatic_rollback=True,published=False,security_status='HOLD'))
    status('driver','failed',2,repr(error));raise
